H.background();
const m = P.m, H0 = P.H0;
const g = 9.8;
const w = H.W, hh = H.H;
const E = m * g * H0;
const x0 = w * 0.12, x1 = w * 0.78, bowlW = x1 - x0;
const groundY = hh * 0.78;
const topY = hh * 0.2;
const px2m = H0 / (groundY - topY);
const u = Math.sin(t * 1.2);
const bx = (x0 + x1) / 2 + (bowlW / 2) * u;
const height = H0 * u * u;
const by = groundY - height / px2m;
const bpts = [];
for (let i = 0; i <= 60; i++) {
  const uu = -1 + 2 * i / 60;
  const xx = (x0 + x1) / 2 + (bowlW / 2) * uu;
  const yy = groundY - (H0 * uu * uu) / px2m;
  bpts.push([xx, yy]);
}
H.path(bpts, { color: H.colors.axis, width: 2.5 });
H.line(x0, topY, x1, topY, { color: H.colors.grid, width: 1, dash: [4, 4] });
H.text("release height H₀", x1 - 110, topY - 8, { color: H.colors.sub, size: 12 });
const r = 11 + m * 1.2;
H.circle(bx, by, r, { fill: H.colors.accent, stroke: H.colors.bg, width: 2 });
H.line(bx, by, bx, groundY, { color: H.colors.violet, width: 1.5, dash: [4, 4] });
const PE = m * g * height;
const KE = Math.max(0, E - PE);
const v = Math.sqrt(2 * KE / m);
const dir = Math.cos(t * 1.2) >= 0 ? 1 : -1;
const aL = 6 + v * 5;
H.arrow(bx, by, bx + dir * aL, by, { color: H.colors.warn, width: 3, head: 10 });
const barX = w * 0.84, barTop = topY, barH = groundY - topY;
H.rect(barX, barTop, 30, barH, { stroke: H.colors.grid, width: 1.5 });
const keH = barH * H.clamp(KE / E, 0, 1);
const peH = barH * H.clamp(PE / E, 0, 1);
H.rect(barX, barTop + barH - keH, 30, keH, { fill: H.colors.good });
H.rect(barX, barTop, 30, peH, { fill: H.colors.violet });
H.text("E", barX + 4, barTop - 8, { color: H.colors.sub, size: 12 });
H.text("Conservation of energy:  KE + PE = E", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("PE = " + PE.toFixed(1) + " J    KE = " + KE.toFixed(1) + " J    E = " + E.toFixed(1) + " J    v = " + v.toFixed(2) + " m/s", 24, 54, { color: H.colors.sub, size: 13 });
H.legend([{ label: "KE", color: H.colors.good }, { label: "PE", color: H.colors.violet }], barX - 70, barTop + 6);
